if(p.startsWith('/api/public/product-event/')&&req.method==='POST'){const id=p.split('/').pop(),pr=await env.DB.prepare('SELECT id,business_id FROM products WHERE id=?').bind(id).first();if(pr)await env.DB.prepare('INSERT INTO product_events(business_id,product_id) VALUES(?,?)').bind(pr.business_id,pr.id).run();return json({ok:true})}
